function largestGoodInteger(num) {
  let best = '';
  for (let i = 2; i < num.length; i++) {
    if (num[i] === num[i - 1] && num[i] === num[i - 2]) {
      const triple = num.slice(i - 2, i + 1);
      if (triple > best) {
        best = triple;
      }
    }
  }
  return best;
}

brute:
function largestGoodInteger(num) {
  for (let digit = 9; digit >= 0; digit--) {
    const candidate = String(digit).repeat(3);
    if (num.includes(candidate)) return candidate;
  }
  return '';
}

