function generate(rand, size) {
  const large = size === 'large';
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const length = large ? pick(900, 1000) : pick(3, 12);
  // A small digit alphabet makes repeated digits, and so triples, more likely.
  const alphabet = [];
  const kinds = large ? pick(2, 10) : pick(1, 4);
  while (alphabet.length < kinds) {
    const d = String(pick(0, 9));
    if (!alphabet.includes(d)) alphabet.push(d);
  }
  // Sometimes forbid three equal digits in a row, so the answer is "".
  const avoid = kinds >= 2 && rand() < 0.3;
  let num = '';
  while (num.length < length) {
    let d = alphabet[pick(0, kinds - 1)];
    while (avoid && num.endsWith(d + d)) d = alphabet[pick(0, kinds - 1)];
    num += !avoid && rand() < 0.15 ? d.repeat(pick(2, 4)) : d;
  }
  return [num.slice(0, length)];
}
